// كتاب العتق — باب إنما الولاء لمن أعتق (ص469–496)
const { NO_N, NO_O } = require('../b4/common');

module.exports = [
  {
    title: `باب إنما الولاء لمن أعتق (ص469–496)`,
    items: [
      { q: `هل يجوز بيع المكاتب؟ (بيع أهل بريرة لها وهي مكاتبة)`, p: `472–473`,
        n: `في حديث عائشة في قصة بريرة أنها كانت مكاتبة فاشترتها عائشة فأعتقتها وأنهم شرطوا ولاءها. المسألة الأولى: أنها كانت مكاتبة وباعها الموالي (أهلها) واشترتها عائشة وأقرّ النبي ﷺ بيعها، فاحتج به طائفة من العلماء في أنه يجوز بيع المكاتب، وممن جوَّزه عطاء والنخعي وأحمد ومالك في رواية عنه. وقال ابن مسعود وربيعة وأبو حنيفة والشافعي وبعض المالكية ومالك في رواية عنه: لا يجوز بيعه. وقال بعض العلماء: يجوز بيعه للعتق لا للاستخدام. وأجاب من أبطل بيعه عن حديث بريرة بأنها عجَّزت نفسها وفسخوا الكتابة.`,
        o: `ابن مسعود وربيعة وأبو حنيفة والشافعي وبعض المالكية ومالك في رواية: لا يجوز بيعه. وقيل: يجوز بيعه للعتق لا للاستخدام. ومن أبطل بيعه قال: بريرة عجَّزت نفسها وفسخوا الكتابة.`,
        s: `الظاهر أن لا (تعجيز)، فهي لم تعجِّز نفسها بل أتت تستعين بعائشة، فالقول الراجح هو صحة بيع المكاتب، فيُباع مكاتَبًا كما كان عند سيده ليس لسيده إلا الأقساط. والمكاتَب: قد أمر الله الأولياء والسادة أن يقبلوا مكاتبة العبيد (وَالَّذِينَ يَبْتَغُونَ الْكِتَابَ مِمَّا مَلَكَتْ أَيْمَانُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا)، فيُكتب ويُتفق معه على أن يؤدي قيمته مقسَّطةً على أقساط، ويُصبح بعد هذا العقد اسمه مكاتَب، فيكون عبدًا ولكن له خصوصية، فيصبح كسبه بدلًا من أن يكون كسبه لسيده ليس عليه إلا أن يُسدد الأقساط، فإذا سددها صار حرًّا، وهذا معنى المكاتَب؛ وإن عجز عن الأقساط رجع عبدًا صِرفًا كما كان، والأقساط التي أدّاها تصبح كالمال الذي يأخذه سيده من كسب عبده.`,
        f: [
          `(ص469 هامش2) على قوله «إن شاءت أن تحتسب عليك»: أي حسبةً وأجرًا على الله.`,
          `(ص470 هامش1) على قوله «تسع أواق»: أي من الفضة، والأوقية أربعون درهمًا، فتسع أواق تساوي [360] درهمًا، وفي ثلاث جرامات تقريبًا فيكون حوالي [1080] جرامًا من الفضة.`,
          `(ص471 هامش1) على قوله «ثم سألته عن زوجها فقال لا أدري»: أي الذي ذكر أن زوجها حرًّا تردد.`,
          `(ص472 هامش2) على قوله «وباعها الموالي»: أي أهلها.`,
        ] },
      { q: `كيف أذن النبي ﷺ لعائشة أن تشترط لأهل بريرة الولاء؟ وهل الشرط الفاسد يفسد البيع؟`, p: `473–474`,
        n: `الموضع الثاني: قوله ﷺ (اشتريها واعتقيها واشترطي لهم الولاء فإن الولاء لمن أعتق) وهذا مشكل من حيث إنها اشترتها وشرطت لهم الولاء وهذا الشرط يفسد البيع، ومن حيث إنها خدعت البائعين وشرطت لهم ما لا يصح ولا يحصل لهم، وكيف أذن لعائشة في هذا؟ ولهذا الإشكال أنكر بعض العلماء هذا الحديث بجملته وهذا منقول عن يحيى بن أكثم واستدل بسقوط هذه اللفظة في كثير من الروايات. وقال جماهير العلماء: هذه اللفظة صحيحة، واختلفوا في تأويلها: فقال بعضهم: (اشترطي لهم) أي عليهم، كما قال تعالى (لهم اللعنة) بمعنى عليهم، وقال تعالى (إن أحسنتم لأنفسكم وإن أسأتم فلها) أي فعليها، وهذا منقول عن الشافعي والمزني وغيرهما. وهو ضعيف لأنه ﷺ أنكر عليهم الاشتراط، ولو كان كما قاله صاحب هذا التأويل لم يُنكره، وقد يُجاب عن هذا بأنه ﷺ إنما أنكر ما أرادوا اشتراطه في أول الأمر. وقيل: معنى (اشترطي لهم الولاء) أظهري لهم حكم الولاء. وقيل: المراد الزجر والتوبيخ لهم، لأنه ﷺ كان بيَّن لهم حكم الولاء وأن هذا الشرط لا يحل، فلما ألحّوا في اشتراطه ومخالفة الأمر قال لعائشة هذا بمعنى لا تبالي سواء شرطتيه أم لا فإنه شرط باطل مردود، فعلى هذا لا تكون لفظة (اشترطي) هنا للإباحة. والأصح في تأويل الحديث ما قال أصحابنا في كتب الفقه: إن هذا الشرط خاص في قصة عائشة، واحتمل هذا الإذن وإبطاله في هذه القصة الخاصة وهي قضية عين لا عموم لها. قالوا: والحكمة في إذنه ثم إبطاله أن يكون أبلغ في قطع عادتهم في ذلك وزجرهم عن مثله، كما أذن لهم ﷺ في الإحرام بالحج في حجة الوداع ثم أمرهم بفسخه وجعله عمرة، وقد تُحتمل المفسدة اليسيرة لتحصيل مصلحة عظيمة.`,
        o: `يحيى بن أكثم: أنكر الحديث بجملته. وقيل: (اشترطي لهم) أي عليهم (الشافعي والمزني). وقيل: أظهري لهم حكم الولاء. وقيل: للزجر والتوبيخ. والأصح عند الشافعية أن الشرط خاص في قصة عائشة، أذن ثم أبطل لتغليظ الزجر.`,
        s: `بلا شك أن الرسول ﷺ قال: (لا يمنعك ذلك منها، ابتاعي وأعتقي)، و«ذلك» أي هذا الشرط الذي اشترطوه. وخلاصة الكلام: أن من طلب شرطًا محرَّمًا وامتنع من الحق الذي عليه في أمر يتشوف فيه الشرع مثل العتق، جاز أن يُشترط له من باب العقوبة ولا يُوفَّى له بهذا الشرط، لأنه اشترط شرطًا محرَّمًا ليس له، فيُقبل ذلك من باب العقوبة إذا كان يعلم حكم الشرع في ذلك. وأصح الأقوال في ذلك أن هذا الشرط لا يُفسد البيع؛ فهذا الشرط فاسد ولكنه خارج عن مقتضى العقد بل منافٍ لمقتضاه، فيبطل الشرط ويصح العقد. مثل من شرط على امرأته حين العقد ألا تُنجب ثم تم الزواج، فلها أن ترجع في هذا الشرط، أو اشترط ألا يقسم لها صحَّ الزواج ولها أن تطالبه بالقسم، أو اشترط ألا ينفق عليها صحَّ الزواج ولها أن تطالبه بالنفقة.` },
      { q: `معنى الولاء وأحكامه: هل يُباع أو يُوهب أو يُنقل أو يثبت بالحِلف؟`, p: `474، 481–482، 496`,
        n: `في حديث بريرة فوائد وقواعد كثيرة، إحداها: ثبوت الولاء للمعتِق. الثانية: أنه لا ولاء لغيره. وفي الباب: قوله (إن رسول الله ﷺ نهى عن بيع الولاء وهبته): فيه تحريم بيع الولاء وهبته، وأنهما لا يصحان، وأنه لا ينتقل الولاء عن مستحقه، بل هو لحمة كلحمة النسب، وبهذا قال جماهير العلماء من السلف والخلف. وأجاز بعض السلف نقله ولعلهم لم يبلغهم الحديث.`,
        o: `أبو حنيفة: يثبت الولاء بالحلف ويتوارثان به. وأجاز بعض السلف نقل الولاء (ولعلهم لم يبلغهم الحديث).`,
        s: `الولاء معناه: ميراث هذا العبد المعتَق الذي صار حرًّا إذا لم يكن له أولاد أو ورثة من العصبة، فلا يوجد أصحاب فروض ولا عصبات، فمن يرثه؟ يرثه أولياؤه؛ فقوله «الولاء لمن أعتق» معناه أن هذا الرجل المعتَق إذا مات عن غير أولاد وعصبات (وغالبًا ما يكون هؤلاء العبيد لا يُعرف لهم عصبات من أولاد العم، فإنهم قد جُلبوا من بلاد أخرى ولا يُعرف لهم نسب) فإن كان له مال فسوف يورثه ورثته، فإن لم يكن له ورثة من أصحاب الفروض والعصبات فيرثه أصحاب الولاء، والولاء كالقرابة، فقد قال ﷺ: «الْوَلَاءُ لُحْمَةٌ كَلُحْمَةِ النَّسَبِ، لَا يُبَاعُ، وَلَا يُوهَبُ» (حب) 4950 [قال الألباني: صحيح لغيره]. وقوله ﷺ «إنما» أسلوب قصر، فلا ولاء لغيره، فلا يجوز أن يُباع ولا يُوهب ولا يُتنازل عنه، ولا يُقال: قد جعلت لك ولاءه، أو أن يجعل الإنسان بالحِلف مثلًا ولاءه لمن تحالف معه ومن تعاقد معه، فيجعل مع آخر اتفاقًا فيما بينهم على أنه إذا لم يوجد لنا ورثة فترثني وأرثك، فيكون هذا الاتفاق اتفاقًا باطلًا لأنه «إنما الولاء لمن أعتق». وهذا الحديث حجة لمن يقول: «لا ولاء للَّقيط ولا ولاء لمن أسلم على يديه رجل»؛ وقد ذكرنا أن عمر ﵁ قد رُوي عنه أنه جعل الولاء لمن التقط اللقيط، وبه قال إسحاق بن راهويه؛ وقال أبو حنيفة: يثبت الولاء بالحِلف ويتوارثان به، فإذا تحالفوا على أمر معين واجتمعوا عليه وتعاقدوا عليه يصحح ذلك أبو حنيفة لقصره الأمر على ذلك. أما ما رُوي عن عمر ﵁ في اللقيط فيمكن أن يُنظر في العلة ويُقال بالقياس، لكن الأصل المنع، لكن لصحة الأثر عن عمر ﵁ في أن الولاء لمن التقط اللقيط وأنه أقرب إليه من بقية المسلمين وربما رعاه ونفعه، ربما أعظم من منفعة المعتِق للمعتَق، والله أعلم. وأما نهيه عن بيع الولاء وهبته: فيكون النهي عنه محرَّمًا وباطلًا ولا ينتقل الولاء، فإنما الولاء لمن أعتق، فهذا حق المنعِم الذي أعتق عبده، فهذا لا يزال إلى أن يموت، لا يمكن أن ينحلَّ كما أن النسب ثابت بالولادة ولا يمكن أن يُباع النسب ولا أن يوهب. وقوله «ولعلهم لم يبلغهم الحديث» بمعنى أنه كما لا يجوز أن تبيع ابنك لغيرك، ولا أن يشتري الإنسان نسبًا، فـ«نهى عن بيع الولاء وهبته» دليل على أنه حتى ولو كان بإذن الموالي — وهم أصحاب الحق — فهو لا يجوز؛ لأنه إنما وُهب، وهذا كما أن النسب لا يُوهب فلا يجوز لأب مثلًا أن يقول لابنه: إنما أذنت لك في أن تنتسب لفلان، كذلك لا يجوز للسيد الذي أعتق عبده أن يقول لعبده: اذهب فقد جعلت ولاءك لفلان، فالولاء كالنسب تمامًا. والحديث فيه إثبات صحة القياس الصحيح في قوله: «الْوَلَاءُ لُحْمَةٌ كَلُحْمَةِ النَّسَبِ، لَا يُبَاعُ، وَلَا يُوهَبُ» (حب) 4950 [قال الألباني: صحيح لغيره].` },
      { q: `من يثبت له الولاء؟ (من أسلم على يديه رجل، والملتقط، والمحالف)`, p: `475`,
        n: `الموضع الثالث: قوله ﷺ (إنما الولاء لمن أعتق). وقد أجمع المسلمون على ثبوت الولاء لمن أعتق عبده أو أمته عن نفسه وأنه يرث به. وأما العتيق فلا يرث سيده عند الجماهير، وقال جماعة من التابعين: يرثه كعكسه. وفي هذا الحديث دليل على أنه لا ولاء لمن أسلم على يديه، ولا للملتقِط اللقيط، ولا لمن حالف إنسانًا على المناصرة، وبهذا كله قال مالك والأوزاعي والثوري والشافعي وأحمد وداود وجماهير العلماء، قالوا: وإذا لم يكن لأحد من هؤلاء المذكورين وارث فماله لبيت المال.`,
        o: `ربيعة والليث وأبو حنيفة وأصحابه: من أسلم على يديه رجل فولاؤه له. وإسحاق بن راهويه: يثبت للملتقِط الولاء على اللقيط. وأبو حنيفة: يثبت الولاء بالحِلف ويتوارثان به. وجماعة من التابعين: يرث العتيقُ سيده كما يرثه سيده.`,
        s: `في قول إسحاق بن راهويه (ثبوت الولاء للملتقِط): لأن هذا ثابت عن عمر ﵁ أنه جعل ولاءه للملتقِط، قال ابن أبي شيبة في مصنفه: [حدثنا ابن عيينة، عن الزهري سمع سنينًا أبا جميلة يقول: وجدت منبوذًا فذكره عريفي لعمر، فأتيته فقال: هو حر، وولاؤك ورضاعه علينا]، وقال البخاري في صحيحه: [باب الولاء لمن أعتق وميراث اللقيط: وقال عمر: اللقيط حر].` },
      { q: `هل يثبت الولاء للمسلم على الكافر وعكسه؟ (وموانع الإرث)`, p: `475–476، 482`,
        n: `وفيه دليل على أنه إذا أعتق عبده سائبة، أي على ألا ولاء له عليه، يكون الشرط لاغيًا ويثبت له الولاء عليه، وهذا مذهب الشافعي وموافقيه؛ وأنه لو أعتقه على مال أو باعه نفسه يثبت له عليه الولاء، وكذا لو كاتبه أو استولدها وعتقت بموته، ففي كل هذه الصور يثبت الولاء، ويثبت الولاء للمسلم على الكافر وعكسه، وإن كانا لا يتوارثان في الحال لعموم الحديث.`,
        o: NO_O,
        s: `بمعنى أنه لو مات المعتَق وسيده كافر فلا يرثه، لكن الولاء له، بمعنى أنه لو أسلم السيد قبل أن يموت المعتَق فسوف يرثه سيده. وثبوت الولاء للمعتِق لعموم «إنما الولاء لمن أعتق»، ولكن قد يمنع من تنفيذ هذا الولاء مانع، مثل أن يموت أحدهما على الكفر، لقوله ﷺ: «لَا يَتَوَارَثُ أَهْلُ مِلَّتَيْنِ شَتَّى» (د) 2911 [قال الألباني: حسن صحيح]، وقد قال تعالى (يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنثَيَيْنِ) فأوجب ﷺ الميراث بالنسب، لكن قد يمنع من ذلك مانع، كأن مات أحد المتوارثين على الكفر، فلا يتوارث أهل ملتين شتى. وإنما هنا نتكلم على أن الولاء كالنسب، فكما ثبت النسب حتى ولو كان أحدهما مسلمًا والآخر كافرًا، فكذا يثبت الولاء؛ فكما لو وُلد لرجل مسلم ولد، وهذا الولد كفر وارتد، فإنه لا يزال ابنه، فإنه إذا مات حال كفره لم يرثه، وأما إذا رجع إلى الإسلام لم ينقطع النسب بل يظل قائمًا، فكذلك الولاء يثبت ولو كان المعتِق أو المعتَق كافرًا، ولا يظهر أثر ذلك إلا إذا كانا مسلمين معًا، وحينها يظهر أثر استعمال الولاء في الميراث في غياب الورثة، فالولاء في الأصل لا يُستعمل كسبب في الإرث إلا إذا غاب أصحاب الفروض والعصبات، فإذا وُجد أصحاب الفروض والعصبات لم يورثه المعتِق بالولاء.` },
      { q: `خيار الأمة إذا عتقت تحت زوج حر (قصة بريرة وزوجها مغيث)`, p: `476–477`,
        n: `الموضع الرابع: أن النبي ﷺ خيَّر بريرة في فسخ نكاحها. وأجمعت الأمة على أنها إذا عتقت كلُّها تحت زوجها وهو عبد كان لها الخيار في فسخ النكاح. فإن كان حرًّا فلا خيار لها عند مالك والشافعي والجمهور. وقال أبو حنيفة: لها الخيار، واحتج برواية من روى أنه كان زوجها حرًّا، وقد ذكرها مسلم من رواية شعبة عن عبد الرحمن بن القاسم، لكن قال شعبة: ثم سألته عن زوجها فقال لا أدري. واحتج الجمهور بأنها قضية واحدة، والروايات المشهورة في صحيح مسلم وغيره أن زوجها كان عبدًا، قال الحفاظ: ورواية من روى أنه كان حرًّا غلط وشاذة مردودة لمخالفتها المعروف في روايات الثقات، ويؤيده قول عائشة: (كان عبدًا ولو كان حرًّا لم يخيَّرها) رواه مسلم. وفي هذا الكلام دليلان: أحدهما إخبارها أنه كان عبدًا وهي صاحبة القضية. والثاني قولها (لو كان حرًّا لم يخيرها). ومثل هذا لا يكاد أحد يقوله إلا توقيفًا، ولأن الأصل في النكاح اللزوم ولا طريق إلى فسخه إلا بالشرع، وإنما ثبت في العبد فبقي الحر على الأصل، ولأنه لا ضرر ولا عار عليها وهي حرة في المقام تحت حر، وإنما يكون ذلك إذا قامت تحت عبد فأثبت لها الشرع الخيار في العبد لإزالة الضرر بخلاف الحر. قالوا: ولأن رواية هذا الحديث تدور على عائشة وابن عباس، فأما ابن عباس فاتفقت الروايات عنه أن زوجها كان عبدًا، وأما عائشة فمعظم الروايات عنها أيضًا أنه كان عبدًا فوجب ترجيحها.`,
        o: `أبو حنيفة: لها الخيار ولو كان زوجها حرًّا (واحتج برواية من روى أنه كان حرًّا). مالك والشافعي والجمهور: لا خيار لها إن كان زوجها حرًّا.`,
        s: `قول عائشة «لو كان حرًّا لم يخيِّرها» له حكم الرفع. وقول الجمهور (الأصل في النكاح اللزوم، وإنما ثبت الخيار في العبد فبقي الحر على الأصل) هذا أرجح.` },
      { q: `هل يسقط حق الأمة في الفسخ إذا تضرر زوجها لشدة حبه لها؟ (مغيث يبكي على بريرة)`, p: `493`,
        n: `الرابعة والعشرون: لها الفسخ بعتقها وإن تضرر الزوج بذلك لشدة حبه إياها، لأنه كان يبكي على بريرة.`,
        o: NO_O,
        s: `أي أن هذا الضرر غير معتبر، وهي مجرد مشاعر للزوج من محبته إياها وهي تكرهه جدًّا، فهذه المشاعر غير معتبرة طالما أن ذلك من حقها.` },
      { q: `الشرط في العقد: ما الشروط الجائزة (مقتضى الإطلاق ومصلحة العاقد) وما الشروط الباطلة؟ وأقسامها`, p: `477–480`,
        n: `الموضع الخامس: قوله ﷺ (كل شرط ليس في كتاب الله فهو باطل وإن كان مائة شرط) صريح في إبطال كل شرط ليس له أصل في كتاب الله تعالى. ومعنى (وإن كان مائة شرط) أنه لو شرطه مائة مرة توكيدًا فهو باطل. قال العلماء: الشرط في البيع ونحوه أقسام: أحدها شرط يقتضيه إطلاق العقد بأن شرط تسليمه إلى المشتري أو تبقية الثمرة على الشجر إلى أوان الجداد أو الرد بالعيب. الثاني شرط فيه مصلحة وتدعو إليه الحاجة كاشتراط الرهن والضمين والخيار وتأجيل الثمن ونحو ذلك، وهذان القسمان جائزان ولا يؤثران في صحة العقد بلا خلاف. الثالث اشتراط العتق في العبد المبيع أو الأمة وهذا جائز أيضًا عند الجمهور لحديث عائشة وترغيبًا في العتق لقوته وسرايته. الرابع ما سوى ذلك من الشروط كشرط استثناء منفعة وشرط أن يبيعه شيئًا آخر أو يكريه داره أو نحو ذلك فهذا شرط باطل مبطل للعقد. هكذا قال الجمهور.`,
        o: `الجمهور: كل ما سوى الأقسام الثلاثة (كاستثناء منفعة أو شرط عقد آخر) شرط باطل مبطل للعقد. وعند الإمام أحمد: يجوز استثناء منفعة معينة (كما في اشتراط جابر حُملان جمله إلى المدينة).`,
        s: `والصحيح أن هذا أيضًا أقسام: فهنالك شروط لمصلحة أحد الطرفين لا تُنافي مقتضى العقد ولكن تُنافي إطلاقه، كما ذكرنا من قبل في شروط النكاح وأنه لو اشترطت عليه ألا يتزوج عليها فهي مصلحة لأحد الطرفين ولا تُنافي مقتضى العقد، فهذا الشرط لا يمنعه ما يقتضيه ذلك العقد، لكن يقيِّد إطلاقه الذي يمنع مقتضاه، مثل أن يقول له «لا تبع هذا ولا تهبه ولا تستعمله»، فمقتضى العقد أصلًا تمليك السلعة للمشتري، وبالتالي فكونه يشترط ما يخالف مقتضاه وما جُعل العقد لأجله فإنه شرط باطل، فهل يبطل به العقد أم لا؟ على قولين للعلماء؛ فهذه الشروط بعض العلماء يقول: إنها شروط باطلة والعقد صحيح، ومنهم من يقول: شروط باطلة ويبطل العقد، لنهي النبي ﷺ عن شرطين في بيع. وهذه الشروط المنهي عنها عند الأكثر: الشرط الأول: ما شُرط في أصل التعاقد وهو ركن البيع، وهو ما شرطوا مثلًا من الثمن، كأن يقول: بعتك هذا بثمن كذا، فلو جعل معه شرطًا آخر يُنافي مقتضى العقد فيُبطلون الشرط وكثير منهم يبطل البيع، وفي النكاح لو شرط مثلًا ألا يُنفق على امرأته أو لا يطأها أو لا يُسكنها، فإن مقتضى عقد النكاح السكن، ومقتضى عقد النكاح المعاشرة، ومقتضى عقد النكاح يلزم منه النفقة، فإذا اشترط ما يُنافي مقتضاه فهذا شرط باطل، وقد ذكر الأكثر في أمر النكاح تصحيح العقد مع بطلان الشروط. وإذا اشترط عقدًا آخر فيه، فهذا عند عامتهم من النوع الباطل، كأن يقول: بعني كذا على أن أبيعك كذا، أو على أن أؤجرك كذا، أو على أن أقرضك كذا، فيشترط عقدًا آخر فيه، وقد نهى رسول الله ﷺ عن بيعتين في بيعة، وهذه أحد الصور في بيعتين في بيعة، ولا يمكن تصحيح أحد العقدين وإبطال الآخر، فلذا عند جمهورهم يبطل العقدان معًا لأن أحدهما شرط في الآخر. وأما اشتراط منفعة، كأن يبيع جملًا أو دابةً ويشترط مدةً معينة يستعملها فيها ثم يسلمها بعدها، كما اشترط جابر في بيع جمله حُملانه إلى المدينة، فلذلك يقول أحمد بصحته، وهذا الحديث يدل على صحة هذا النوع من الشروط، فاستثناء منفعة معينة مثل أن يقول له: بعتك هذه الدار ولكن أسكنها لمدة شهر حتى أُدبِّر دارًا غيرها، ويُسلِّم الثمن وبعد شهر يخرج منها، فاستثناء منفعة معينة، فهذا عند أحمد يجوز، وعند الأكثر لا يجوز كما ذكره هنا النووي رحمه الله بل جعله مبطلًا للعقد، والصحيح أن شرط استثناء منفعة معلومة ليس مبطلًا للعقد ولا هو شرطٌ باطل أصلًا ولا يُنافي مقتضى العقد وإنما يُنافي إطلاقه؛ لأنه إذا قال: بعتك هذه الدار أو هذه السيارة دون أن يشترط، فالأصل أنه قد ملَّكه إياها فور انتهاء العقد، ويلزمه تسليم ذلك بمجرد انتهاء العقد، فإذا شرط ما يُنافي ذلك كان منافيًا لمقتضى العقد؛ ولكن إذا اشترط منفعة معلومة لمدة يتم بعدها التسليم فهذا شرط لا يُنافي إطلاق العقد ولا يُنافي مقتضاه، ومقتضاه هو الذي يقتضيه ذلك العقد من تمليك السلعة أو ما يقتضيه كما ذكرنا في النكاح. وهذا الأمر الذي يظهر من مذهب الإمام أحمد رحمه الله، لأن هذه الكلمة عن الإمام أحمد «لا يبطله شرط واحد» اختلفوا فيها اختلافًا كثيرًا في تفسيرها، والصحيح أنه جنس معين من الشروط؛ والإمام أحمد ضعَّف حديث (نهى عن بيع وشرط) وإنما نهى عن شرطين في بيعة هو الصحيح، فهذا الذي قاله أحمد هو نص الحديث، لكن تفسير الحديث وبالتالي تفسير كلام الإمام أحمد: ما هو المقصود بالشرطين في بيعة؟ الصحيح أنه شرط إضافي إلى العقد من جنس الشروط المنافية لمقتضاه، فيكون قد نهى عن شرطين في بيع هما من جنس واحد، فالبيع اقتضى شيئًا وشُرط معه شرطٌ يُنافيه، فهما في الأصل من باب واحد، لأن الأصل مثلًا أن من حقي أن أتصرف في السلعة التي في يدي طالما أنها ملكي، ومن حق الآخر أن يتصرف في السلعة إذا صارت ملكه، فإذا شُرط شرطان متضادان من نفس الدرجة والقوة ومن نفس النوع، مثل ما ذكروه في نكاح الشغار أيضًا، فهذه الشروط هي الشروط المبطلة ويبطل البيع في تلك الحال، والله أعلى وأعلم؛ فالمقصود بجنس من الشروط المبطلة بالإضافة إلى الشرط الذي اقتضاه العقد، أو هو في الحقيقة ركنٌ في البيع؛ لأن كلمة الشرط في الحقيقة استُعملت في الشرع استعمالًا أوسع من الاستعمال الاصطلاحي لكلمة الشرط، وهي أصلًا في اللغة كذلك أوسع من الاستعمال الاصطلاحي، فالاستعمال الاصطلاحي في الشرط هو: ما لا يلزم من وجوده وجود ويلزم من عدمه العدم، وذلك في العقود وفي العبادات ونحوها، وهو شيء خارج عن الماهية يلزم من عدمه عدم تلك الماهية، ولا يلزم من وجوده وجود، كالوضوء مع الصلاة مثلًا، فهذا هو الاستعمال الاصطلاحي؛ ويستعملون الركن في الاستعمال الاصطلاحي فيما هو في أساس العقد وكونه جزءًا من الماهية يلزم من وجوده وجود ويلزم من عدمه العدم. فالإيجاب والقبول ركنان في الاصطلاح وقد يُستعملان بلفظ الشرط في الاصطلاح الشرعي، ولذلك نهى عن شرطين في بيع، فعندما يقول: بعتك كذا على أن تؤجرني كذا، جعلوا ذلك شرطين في بيعة، مع أنه في الحقيقة عند التأمل هما عقدان دخل في بعضهما كلٌّ من العقدين له أركان تداخلت، ومع هذا قد سموا هذا شرطين في بيع، فدل ذلك على أن الاستعمال الشرعي لكلمة الشرط أوسع من الاستعمال الاصطلاحي كما ذكرنا، فقد يُطلق على الركن وقد يُطلق على الشرط. فالنوع الرابع هذا لا بد فيه من التفرقة بين استثناء منفعة وبين اشتراط عقد آخر فيه وهو نهيه ﷺ عن بيعتين في بيعة، وهو شرطين في بيع، بنفس المعنى عند الكثيرين. وبعض التفسيرات عن أحمد يرى أنه لو شرط عليه مثلًا أن يشتري منك هذا الثوب على أن تصنعه لي، منهم من يمنعه ويُبطله وأكثر العلماء لا يرون مانعًا في ذلك، يقول: أنه يشتري القماش وتُفصله لي، أو أشتري المادة الخام وتصنعها لي، مثل المقاولات المعروفة يشترط الأمرين معًا فيشترط شراء المادة التي تُصنع ويشترط تصنيعها؛ والحنابلة أكثرهم يُبطل الاثنين معًا، ويشترط فصلهما عن بعضهما.`,
        f: [
          `(ص477 هامش1) على قوله «شرط يقتضيه إطلاق العقد»: والمعنى أنه إذا أُطلق العقد ولم يُقيَّد بشروط معينة فالأصل فيه أن المبيع يُسلَّم إلى المشتري، وإذا اشترى ثمرةً بعد بدو الصلاح فهو يشتريها حتى تكتمل، فمقتضى العقد أنه طالما لم يشترط عليه أن يقطع الآن فإنه يُبقي الثمرة إلى أوان الجُداد، أو أنه إذا اشترى سلعة ليس بها عيب فإنه إذا ظهر عيب يردُّه بالعيب، فمثل هذه الشروط واجب الوفاء بها لأنها من مقتضى إطلاق العقد.`,
          `(ص477 هامش2) على قوله «كاشتراط الرهن والضمين والخيار وتأجيل الثمن»: بمعنى أن يكون هناك اشتراط في وجود رهن للثمن، أو اشتراط أن يكون هناك ضامن بمعنى أنه إذا لم تؤدِّ في الموعد سوف آخذ الثمن من فلان فهو يضمنك، وكذا شرط الخيار وهي مدة زائدة على مجلس التعاقد زائدة على خيار المجلس، وكذا يُشترط تأجيل الثمن إلى أقساط معينة، وهي ليست من إطلاق العقد ولا تُستفاد من إطلاقه بل لا بد من النص عليها، لكن هي لمصلحة أحد الطرفين.`,
          `(ص478 هامش1) على قوله «لقوته وسرايته»: معنى «سرايته» أنه يسري على الجزء غير المعتَق كما فيمن أعتق شقصًا له في عبد، فهو يسري على الجزء الآخر الذي لم يُعتقه صاحبه ويُقوَّم على المعتِق قيمة عدل، ويُعتق العبد كله ويُعطى الشركاء نصيبهم من مال المعتِق، هذا كله لقوة العتق وسرايته وترغيب الشرع فيه.`,
        ] },
      { q: `تصحيح الشروط التي دلّت عليها أصول الشرع: هل يُشترط ورود النص؟ (الشرط الجزائي، وبيعتان في بيعة)`, p: `486`,
        n: `الحادية عشر: تصحيح الشروط التي دلت عليها أصول الشرع وإبطال ما سواها.`,
        o: NO_O,
        s: `قوله ﷺ (ما كان من شرط ليس في كتاب الله عز وجل فهو باطل) عند كثير من العلماء معناه «في كتاب الله إبطاله»، وهذا هو الظاهر، فليس في كتاب الله أي ليس في شرعه، فكل شرط في كتاب الله بُطلانه لا يُوفى به وهو باطل. وقلنا ذلك لأن النبي ﷺ قال (المسلمون عند شروطهم)، وظاهر هذا الحديث صحة العقد مع بطلان الشرط، وقال (أحق ما أوفيتم من الشروط أن توفوا به ما استحللتم به الفروج) البخاري، فهذا حق وما سواه حق طالما اشترط على نفسه شروطًا جائزة، وليس معلومًا أن الشرع نص لنا على الشروط التي يسوغ لنا أن نشترطها، بل الشرع أطلق، فكتاب الله ﷻ ليس فيه بيان اشتراط كذا وكذا فقط، وإنما بيَّن الشرع مقتضيات العقود جملةً وما يصح وما لا يصح، فتبيَّن بذلك أنه لم ينص على عدد معين من الشروط، ومن أجل هذا لا يُشترط أن يكون النص منصوصًا عليه في الكتاب أو السنة، بل يكفي أن يكون مثاله قد دلَّ عليه الكتاب والسنة، ولذلك قالوا (تصحيح الشروط التي دلت عليها أصول الشرع) فالشرع وسَّعه ودلَّ على اعتبارها وليس على إبطالها، فما أبطلها الشرع فهي الباطلة. ومثال ذلك اشتراط شرط جزائي مثلًا عقوبةً على فسخ العقد، فأكثر العلماء المعاصرين يرون صحة هذا الشرط بناءً على أن المسلمين عند شروطهم، لأن هذا قد اشترط على نفسه أنه إن فسخ العقد خلال مدة معينة يدفع مبلغًا معينًا، فهذا ليس منصوصًا على جوازه ولكن داخل في العمومات التي فيها الوفاء بالشروط، والله أعلم. وأما الشروط التي أبطلها الشرع فلا بد وأن تُبطل، كنكاح الشغار وكأن يشترط عقدًا آخر كما ذكرنا بمعنى: بعتك كذا على أن أبيعك كذا، أو بمعنى: داري لك على أن أؤجر لك سيارتي، بمعنى أن العقدين منفصلان، فمن الممكن أن تكون أجرة السيارة ثمن الدار، والاثنان عقد واحد والثمن غير محدد؛ وأما بمعنى: المنزل بكذا على أن أبيعك السيارة بكذا، ويشترطوا أن كلا العقدين داخل كل منهما في الآخر، فهذا لا يجوز.` },
      { q: `قوله ﷺ «هو لها صدقة ولنا هدية»: إذا تغيرت صفة المال تغيّر حكمه (وتطبيقه على مال الربا ومجهول المالك)`, p: `480–481`,
        n: `الموضع السادس: قوله ﷺ في اللحم الذي تُصدِّق على بريرة به: (هو لها صدقة ولنا هدية) دليل على أنه إذا تغيرت الصفة تغير حكمها، فيجوز للغني شراؤها من الفقير وأكلها إذا أهداها إليه، وللهاشمي ولغيره ممن لا تحل له الزكاة ابتداءً.`,
        o: NO_O,
        s: `إذا قبض الفقير الصدقة أو الزكاة فقد صارت ملكًا له، فله أن يتصرف فيها كيف يشاء ولو بالإهداء أو بالبيع، فلا يلزم أن يأكلها بنفسه، فالأمر أصبح ملكًا له. ولذا في قول النبي ﷺ: «لَا تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ إِلَّا لِخَمْسَةٍ: لِعَامِلٍ عَلَيْهَا، أَوْ لِغَازٍ فِي سَبِيلِ اللهِ، أَوْ لِغَنِيٍّ اشْتَرَاهَا بِمَالِهِ، أَوْ فَقِيرٍ تُصُدِّقَ عَلَيْهِ فَأَهْدَاهَا لِغَنِيٍّ، أَوْ غَارِمٍ» (جة) 1841 [قال الألباني: صحيح]. فبعد أن تُصدِّق بها على الفقير ظهر للفقير حاجات أخرى أو كان عنده منها أكثر، فأُعطيت له فباعها ليأتي بالحاجات الأخر، فهي له صدقة وإذا باعها الغني لم تكن محرمة على الغني لأن صفة الصدقة قد تغيَّرت، ولذا جاز للنبي ﷺ وللهاشمي من بعده ولكل بني هاشم وبني المطلب ممن تحرم عليهم الصدقة أن يأكلوها بوصف الهدية. ومن هنا نقول مثلًا: إذا تاب آكل الربا ولم يعلم الشخص الذي يجب عليه أن يرد له مال الربا الزائد، وهذه الأموال التي في يده أصبحت مجهولة المالك لأنها موزعة على مالكين متعددين مجهولين ممن أخذ منهم هذا المال، ولا يقدر على إيصاله إلى أصحابه، فيتصدق به عنهم، فهذه صفة مغايرة، فلذلك يجوز للفقير أن يأكل منها لأنها الآن ليست مالًا ربويًّا محرَّمًا، وإنما هو يُتصدَّق بها عن أصحابها المجهولين، فتغيرت الصفة. ولذا لا يُحرم أن تُجعل في الطعام والشراب للفقراء، لا كما يظن البعض أنه يلزم أن تُجعل في دورات المياه أو أن تُجعل في أسفل الطرق، فيشترطون شروطًا عجيبة؛ مع أن الحديث الموقوف الذي ورد في ذلك أن ابن مسعود جعل يتصدق عن رب الجارية، وهو الأصل الذي بُني عليه التصرف في المال مجهول المالك بدلًا من إمساكه. ومن يقول: لا يتصرف تصرف ابن مسعود، يقول: يُحبس هذا المال حتى يظهر صاحبه ولو تلف، وبعضهم قال: يُلقى في البحر ونحو ذلك من الأقوال الضعيفة جدًّا التي لا تأتي بمثلها الشريعة، وهو أن يفسد المال على صاحبه وعلى من في يده وعلى المسلمين عمومًا، لكن الذي تصرَّف فيه الصحابة ﵃ مثل تصرف الفضولي وهو أنه يتصدق به عنه، فصار هذا المال المملوك لبعض الناس لكننا لا ندريهم؛ فمال الربا في الحقيقة لا بد وأن يُرد إلى من أُخذ منه، لكنه يعجز الآن عن رده لأنهم أشخاص متعددون جدًّا ولا سبيل إلى معرفتهم ولا الوصول إليهم، فعند ذلك يتصدق به عنهم والله أعلم بهم، وكالغالّ من الغنيمة إذا تصدق به عن بقية أفراد الجيش، فإنه يتصدق به عنهم بما يغلب على الظن أنهم يقبلون هذا التصرف؛ وهذا مخرجه في هذا الباب، يتصرف فيه دون إذنهم لكن بما يغلب على الظن أنهم يقبلون هذا التصرف، وفي يوم القيامة سوف يفرحون بالصدقات، أما إذا عُلم في الدنيا وأبى ذلك التصرف ضمن له المال وأعطاه له مرة أخرى وأخذ هو الثواب. وعلى هذا فالصفة التي أُنفق بها هذا المال قد تغيرت، ولذا جاز أن يُوضع في المساجد، وليس كما يقول البعض: لا يجوز وضعه في المساجد ولا في الأكل والشرب، بل ليس كذلك؛ فإنه لا يجوز وضعه في المساجد إذا كان يتصرف في المال على أنه ماله هو، فيكون كالمال المغصوب الذي لا يُبنى به المسجد، وكالمال المسروق لا يقبله الفقير طعامًا وشرابًا لأنه يجب أن يُرد إلى صاحبه طالما أمكن ذلك، فإذا تصرف فيه تصرف المالك بطل هذا التصرف ولم يصح، فلا يتملكه الفقير لأنه أخذه من غير مالكه. لكن لو أخذه على صفة أنه تاب إلى الله وتصدق به عن صاحبه فقد تغيرت الصفة، ولذا جاز أن يوضع في المسجد وجاز أن يستعمله في طعامه وشرابه وكسوته وجاز أن يُبنى به ما يحتاج إليه المسلمون، ولا يُشترط وضعه في دورات المياه ونحو ذلك؛ وإلا فهذا الأمر محرَّم لو كان على صفة أنه يعرف صاحب المال، فلو أنه سرق مالًا وهو يعرف صاحبه هل يجوز أن يجعله في دورة مياه للمسجد؟ لا يجوز له ذلك وحرام عليه ولا يجوز استعمال دورة المياه بهذه الطريقة، لأنها لم تُنشأ بمال رضي به صاحبه، ولكن عليه أن يتوب إلى الله ويعطي المال لصاحبه، أو إذا عُدم ذلك المال وتلف يضمنه له، ثم بعد ذلك يكون التصرف صحيحًا. الغرض المقصود أنه إذا تغيرت الصفة تغير حكم الشيء، وهو من قول النبي ﷺ: «هُوَ لَهَا صَدَقَةٌ وَلَنَا هَدِيَّةٌ».` },
      { q: `ثبوت الولاء للمعتِق، وأن لا ولاء لغيره؛ وجواز الكتابة (فوائد حديث بريرة الأولى والثانية والرابعة)`, p: `481–482`,
        n: `واعلم أن في حديث بريرة هذا فوائد وقواعد كثيرة، وقد صنَّف فيه ابن خزيمة وابن جرير تصنيفين كبيرين: إحداها ثبوت الولاء للمعتِق. الثانية أنه لا ولاء لغيره. الثالثة ثبوت الولاء للمسلم على الكافر وعكسه. الرابعة جواز الكتابة.`,
        o: NO_O,
        s: `(ثبوت الولاء للمعتِق) وهذا نص الحديث ومقصوده الأول، وعليه بوَّب حيث قال (باب إنما الولاء لمن أعتق). (لا ولاء لغيره) لقوله ﷺ (إنما) أسلوب قصر. (جواز الكتابة) ولقوله تعالى (وَالَّذِينَ يَبْتَغُونَ الْكِتَابَ مِمَّا مَلَكَتْ أَيْمَانُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا) فالكتابة مشروعة بالاتفاق، وقد ذكر هنا الجواز لأن الحديث يدل على جوازها ومشروعيتها لأن بريرة كاتبت أهلها، بمعنى أنها اتفقت معهم على تسديد قيمة معينة على أقساط تصير بعدها حرة، إذا كاتب السيد عبده واتفق معه على ذلك، سواء كتب أو لم يكتب، فمقصود الكتابة الاتفاق على ذلك، فطالما اتفقا على تسديد أقساط فهذه مكاتبة.` },
      { q: `هل الكتابة واجبة على السيد إذا عُلم في العبد خير؟`, p: `482–483`,
        n: NO_N,
        o: `الجمهور: الكتابة مستحبة لا واجبة. وعمر ﵁ ألزم أنسًا بمكاتبة سيرين (وقال ابن جريج لعطاء: أواجب عليّ إذا علمت له مالًا أن أكاتبه؟ قال: ما أراه إلا واجبًا، وقاله عمرو بن دينار).`,
        s: `وظاهر الآية وجوب المكاتبة إذا عُلم في العبد أو الأمة خيرًا، على تفصيل في تفسير «الخير»، فمنهم من يقول: قدرة على الكسب، ومنهم من يقول: «الخير» بمعنى الإيمان والطاعة ونحو ذلك، فإذا عُلم فيه ذلك وطلب المكاتبة فظاهر الآية الوجوب، وهو ظاهر قول عمر ﵁ مع أنه خلاف قول الجمهور. قال البخاري في صحيحه: [باب المكاتب ونجومه في كل سنة نجم: وقوله (وَالَّذِينَ يَبْتَغُونَ الْكِتَابَ مِمَّا مَلَكَتْ أَيْمَانُكُمْ فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا وَآتُوهُمْ مِنْ مَالِ اللَّهِ الَّذِي آتَاكُمْ)، وقال روح عن ابن جريج قلت لعطاء أواجب عليّ إذا علمت له مالًا أن أكاتبه؟ قال: ما أراه إلا واجبًا، وقاله عمرو بن دينار. قلت لعطاء: تأثره عن أحد؟ قال: لا. ثم أخبرني أن موسى بن أنس أخبره أن سيرين سأل أنسًا المكاتبة، وكان كثير المال، فأبى، فانطلق إلى عمر ﵁ فقال: كاتبه، فأبى، فضربه بالدِّرَّة ويتلو عمر (فَكَاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْرًا) فكاتبه]، فألزمه عمر ﵁ بالمكاتبة على ظاهر الآية، وهذا هو الصحيح، وهو أن العبد إذا رغب في المكاتبة وكان قادرًا على الكسب وكان دينًا ليس فاسقًا ولا فاجرًا، وجب على السيد أن يُجيبه على ذلك، وذلك في كل عبد أيًّا ما كان أراد المكاتبة وعُلم فيه الخير، لزم سيده أن يُكاتبه وأن يقبل ذلك، فقد فتح الإسلام الباب أمام العبيد لمن أراد منهم أن يُعتق بالمكاتبة، ويُلزم الإسلام السادة بذلك، وهذا من أعظم ما رفعه الإسلام من شأن العبيد وأعطاهم من حقوق بها فيها حق أنه يستطيع أن يتحرر إذا أراد ذلك، وذلك بإلزام السيد بمكاتبته، فلم يعد هناك وجود لتلك الصورة المهينة للعبيد التي لا يستطيع الخروج منها حياته كلها.` },
      { q: `فسخ الكتابة إذا عجَّز المكاتب نفسه، وجواز كتابة الأمة (ودخول النساء في صيغة المذكر)`, p: `483`,
        n: `الخامسة: جواز فسخ الكتابة إذا عجَّز المكاتب نفسه، واحتج به طائفة على جواز بيع المكاتب كما سبق. السادسة: جواز كتابة الأمة كالعبد.`,
        o: `الشافعية يختارون أن بيع المكاتب لا يجوز، فجعلوا الحديث دليلًا على جواز فسخ الكتابة عند العجز.`,
        s: `(1) مأخوذ من أن عائشة ﵂ تريد أن تشتريها بناءً على أنها تُعجِّز نفسها فتسقط الكتابة فتشتريها عائشة ﵂ على أنها ليست مكاتبة ولكن مملوكة تمامًا، فعند ذلك تشتريها وتعتقها بعد ذلك. (2) قوله «واحتج به طائفة» وذلك لأن الشافعية يختارون أن بيع المكاتب لا يجوز، فقد جعلوا الحديث دليلًا على جواز فسخ الكتابة، فبعد أن يُسدد بعض الأقساط أو لم يسدد منها شيئًا وعجز عن السداد، فيصبح المال الذي دفعه ملكًا للسيد كما هو ويصبح العبد عبدًا مرة ثانية طالما أن العبد هو الذي قال: أنا عجزت ولا أريد الاستمرار في تسديد الأقساط. والصحيح في المسألة الخامسة أن يُقال: جواز بيع المكاتب مكاتبًا كما كان، لأنه لم يرد في الحديث فسخ الكتابة، ولا أنها قد عجزت نفسها. (3) فيكون قوله تعالى (وَالَّذِينَ يَبْتَغُونَ الْكِتَابَ مِمَّا مَلَكَتْ أَيْمَانُكُمْ فَكَاتِبُوهُمْ) تشمل الذكور والإناث، فرغم أنها وردت بصيغة المذكر، لكن لأن المذكر إذا دخل في جماعة الإناث ولو كان واحدًا أُخبر عن الجميع بصيغة الذكور، فلو خاطبت أو أخبرت عن رجل ومجموعة نساء فسوف تُخبر عنهم أو تخاطبهم بصيغة المذكر، إذًا لا يدل ذلك على عدم دخول النساء في هذه الصيغة؛ إذًا هذه المسألة (مسألة المذكر مع مجموعة نساء، فضلًا عن أن يكونوا ذكورًا وامرأة واحدة) هي مسألة زيارة القبور للنساء، لأن قول النبي ﷺ (نهيتكم عن زيارة القبور فزوروها) مسلم، فشيخ الإسلام يقول: إن هذا خاص بالرجال لأنها صيغة مذكر؛ والجمهور قالوا: بل هذا قد دخل فيها الجميع رجالًا ونساءً، وبصيغة المذكر يُخاطب النبي ﷺ بها الأمة، فكل الأوامر الشرعية كقوله تعالى (يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ) فقد دخل فيها الإناث باتفاق، فلو أن امرأة ماتت وتركت أولادًا فهم يرثونها بنفس الطريقة بلا نزاع عند العلماء، وكل الأحكام الشرعية التي يشترك فيها الرجال والنساء خُوطب فيها الجميع بصيغة المذكر، فليس هناك من يقول بأنه خرج منها النساء لأن العرب تستعمل ذلك، فالأصل استواء أحكام الرجال والنساء إلا ما دلَّ عليه الدليل، فشيخ الإسلام يجعل الدليل قوله ﷺ: (لَعَنَ رَسُولُ اللهِ ﷺ زَوَّارَاتِ الْقُبُورِ) (جة) 1574 [قال الألباني: حسن]؛ والجمهور قالوا: إن هذا عندنا كان منهيًّا عنه منسوخًا أو محمولًا على الزيارة غير الشرعية، ويؤكد هذا أن الرسول ﷺ لم يعزم على النساء في ترك اتباع الجنائز، حيث قالت أم عطية: (نُهينا عن اتباع الجنائز ولم يُعزم علينا) متفق عليه، فدل على أنه لا بد أن يذهبوا إلى القبور طالما تبعت الجنازة ولم يُعزم عليها في النهي، إذًا كان مكروهًا، فكيف يكون ملعونًا؟ وقد علَّم النبي ﷺ عائشة دعاء دخول المقابر، فدل ذلك على أن قوله (زوَّارات القبور) كان على الزيارة غير الشرعية أو على الزيارة الشرعية عندما كان منهيًّا عنها الرجال والنساء. فهذه الآية وإن وردت بصيغة المذكر فالأَمَة كالعبد في مشروعية الكتابة.` },
      { q: `جواز كتابة المزوَّجة، وهل يصير المكاتب حرًّا بنفس الكتابة أو بأداء جزء المال؟`, p: `484`,
        n: `السابعة: جواز كتابة المزوجة. الثامنة: أن المكاتب لا يصير حرًّا بنفس الكتابة بل هو عبد ما بقي عليه درهم كما صرَّح به في الحديث المشهور في سنن أبي داود وغيره، وبهذا قال الشافعي ومالك وجماهير العلماء. وحكى القاضي عن بعض السلف أنه يصير حرًّا بنفس الكتابة ويثبت المال في ذمته ولا يرجع إلى الرق أبدًا. وعن بعضهم أنه إذا أدى نصف المال صار حرًّا ويصير الباقي دينًا عليه. قال: وحُكي عن عمر وابن مسعود وشريح مثل هذا إذا أدى الثلث. وعن عطاء مثله إذا أدى ثلاثة أرباع المال.`,
        o: `بعض السلف: يصير حرًّا بنفس الكتابة ويثبت المال في ذمته. وبعضهم: إذا أدى النصف. وعمر وابن مسعود وشريح: إذا أدى الثلث. وعطاء: إذا أدى ثلاثة أرباع المال.`,
        s: `فكونها مزوَّجة لا يلزم من ذلك امتناع الكتابة، وإن كان زوجها له حقٌّ فيها، لكن حقها في إعتاق نفسها، وربما يكون ذلك سببًا في انفصالها عن زوجها، حقٌّ لا يُسقطه زواجها، وخصوصًا إذا تأكد أنها ربما تُعجِز نفسها وترجع عبدًا مملوكًا كما كان. وأما الأقوال المحكية عن بعض السلف فكل هذا لا دليل عليه، وعندنا حديث (المكاتَب عبدٌ ما بقي عليه من مكاتبته درهم) (د) 3926 [قال الألباني: حسن]، دليل على أنه لا يزال عبدًا حتى يُسدد آخر قسط من المكاتبة.` },
      { q: `هل تجوز الكتابة على نجم واحد أم لا بد من نجمين فصاعدًا؟`, p: `484–485`,
        n: `التاسعة: أن الكتابة تكون على نجوم لقوله في بعض روايات مسلم هذه: إن بريرة قالت: إن أهلها كاتبوها على تسع أواق في تسع سنين كل سنة أوقية. ومذهب الشافعي أنها لا تجوز على نجم واحد بل لا بد من نجمين فصاعدًا. وقال مالك والجمهور: تجوز على نجوم وتجوز على نجم واحد.`,
        o: `الشافعي: لا بد من نجمين فصاعدًا. مالك والجمهور: تجوز على نجوم وعلى نجم واحد.`,
        s: `وهذا هو الصحيح (قول مالك والجمهور)، فلا دليل على لزوم أن تكون على نجمين فصاعدًا. (يُسمُّونه نجمًا، فالنجوم أي الأقساط.)` },
      { q: `خيار الأمة إذا عتقت تحت عبد: اشتراط الكفاءة في الدين والحرية، وعضل الأولياء`, p: `485–486`,
        n: `العاشرة: ثبوت الخيار للأمة إذا عتقت تحت عبد.`,
        o: `من وسّع في الكفاءة: قال الكفاءة في النسب والصنعة واليسار، فيجعل للأولياء حق الاعتراض ويُبطل العقد إذا اعترض أحدهم.`,
        s: `وهذا الذي نقول به أنه دليل على اشتراط الكفاءة في الحرية، فلو جاء عبد يريد أن يتزوج بنتًا حرة لأحرار وهي تريده، هل من حق أوليائها أن يعترضوا ولا يكونون بذلك عاضلين؟ نعم، فإنهم إذا اعترضوا في تلك الحالة ليس لها أن تجعل ولايتها للقاضي ولا لآخرين إذا غاب القاضي — السلطان — لأنهم عضلوها ومنعوها من الزواج بحق، فليس هو عاضلًا باطلًا فيفسق فتسقط ولايته، وإنما له أن يمنعها من الزواج ممن تريد إذا كان غير كفء لها. وقد ذكرنا أن الكفاءة في الدين والحرية على أصح أقوال العلماء، ومن وسَّع منهم وقال: الكفاءة في النسب والكفاءة في الصنعة والكفاءة في اليسار، فهو يجعل للأولياء حق الاعتراض ويُبطل العقد إذا اعترض أحدهم. والصحيح أنه لا اعتبار إلا بالدين والحرية، فإنه إذا جاء فاسق يطلب امرأة تقية دينة وهي تريده وتحبه، وامتنع أبوها أو أحد أوليائها، لم يكن لها أن تُسقط ولايتهم ولو تزوجت بولاية أخرى حتى ولو ولاية السلطان كان هذا الزواج باطلًا. أما إذا جاء فقير يخطب امرأة غنية أو بنت أغنياء، أو من ليس له نسب فجاء يخطب قرشية أو شريفة هاشمية، أو جاء من هو ذو مهنة حقيرة في ظن الناس (وَاتَّبَعَكَ الْأَرْذَلُونَ) مثل الحجام مثلًا، فجاء يخطب بنت تاجر أو نجار أو بائع أو حداد أو غير ذلك من المهن الشريفة عند العلماء لأنها مهن الأنبياء، فالكفاءة عند العلماء بهذا الاعتبار وإن استنكر ذلك أهل زماننا؛ ومع ذلك فالكفاءة في المهن أصلًا غير معتبرة على الصحيح من أقوال العلماء. فالمرأة إن أرادته فلا يجوز لوليها أن يمنعها ولو حتى أبوها؛ رجل فقير وهي تريد أن تتزوجه، نقول: يجب عليه أن يُزوِّجها طالما صرَّحت أنها تريده. وقد يعرض دون مهر المثل، فلو مهر مثلها عشرون ألفًا، فيقول: ليس معي إلا خمسة أو ألف، وهي تريده مع ما دون مهر المثل، يلزم وليَّها تزويجها وإلا كان عاضلًا، داخلًا في قول الله ﷻ (فَلَا تَعْضُلُوهُنَّ أَنْ يَنكِحْنَ أَزْوَاجَهُنَّ) فهو مثل ذلك، حتى ولو لم يكن زوجها، والآية قد نزلت في المبالغة: فكان زوجًا لها ثم تركها حتى انتهت عدتها ثم تقدم لها كخاطب، فمنع الشرع الولي أن يعضلها، فبالأولى إذا كان من البداية، فليس للولي أن يمنعها من الزواج ممن تريد إذا كان كفؤًا لها في الدين والحرية كما ذكرنا. فإذا كان الأمر كذلك وامتنع الولي سقطت ولايته، وجاز للسلطان أن يُزوِّجها، لقول النبي ﷺ: (فَإِنْ تَشَاجَرُوا فَالسُّلْطَانُ وَلِيُّ مَنْ لَا وَلِيَّ لَهُ) (د) 2083 وصححه الألباني في الإرواء: 1840، فأي مشاجرة في ذلك ويكون الولي ظالمًا، فالسلطان يُصبح هو الولي، وإذا غاب السلطان قام مقامه أهل العلم أو عدل من المسلمين، حتى لا يمتنع نكاح هذه المرأة المظلومة التي تريد أن تتزوج، فبعض الأهالي يمتنعون ويقولون: سوف لا تتزوج فلان وهي تريده وهو كفؤ لها، فليس لهم ذلك ويمكن أن تتزوج كما ذكرنا. أما إذا كان عبدًا وهي حرة، أو إذا كان فاسقًا وهي تقية، فليس هو بكفء لها، فلا تسقط ولاية الولي إن اعترض، وإذا اعترض أحد الأولياء بطل العقد.` },
      { q: `جواز الصدقة على موالي قريش (موالي أزواج النبي ﷺ) ومن تحرم عليه الصدقة`, p: `486–487`,
        n: `الثانية عشر: جواز الصدقة على موالي قريش. الخامسة عشر: أن الصدقة لا تحرم على قريش غير بني هاشم وبني المطلب؛ لأن عائشة قرشية وقبلت ذلك اللحم من بريرة على أن له حكم الصدقة وأنها حلال لما دون النبي ﷺ ولم ينكر عليها النبي ﷺ هذا الاعتقاد.`,
        o: NO_O,
        s: `لأن بريرة مولاة لعائشة ﵂، كانت أمةً وحرَّرتها عائشة ﵂، وكان يُتصدَّق باللحم عليها، بل يدل الحديث على جواز الصدقة على موالي أزواج النبي ﷺ، مع أن أزواج النبي ﷺ محرَّم عليهم الصدقة، لكن مواليهم المعتَقين يظهر — والله أعلى وأعلم — جواز الصدقة عليهم. وأما حديث (مَوْلَى الْقَوْمِ مِنْ أَنْفُسِهِمْ، وَإِنَّا لَا تَحِلُّ لَنَا الصَّدَقَةُ) (د) 1650 [قال الألباني: صحيح]، وفي رواية عند أحمد (إِنَّا — آلَ مُحَمَّدٍ — لَا تَحِلُّ لَنَا الصَّدَقَةُ، وَإِنَّ مَوْلَى الْقَوْمِ مِنْ أَنْفُسِهِمْ) (حم) 27182، فهذا إذا كان مولى الرسول ﷺ وبني هاشم مباشرةً، وليس مولى زوجاته. فالصحيح أن موالي بني هاشم وبني المطلب من آل البيت، ويُحتمل غير ذلك، وأن يكون كما ذكرنا أن موالي أزواج النبي ﷺ ليسوا كذلك. والذي يظهر — والله أعلى وأعلم — أن قوله ﷺ (هُوَ لَهَا صَدَقَةٌ وَلَنَا هَدِيَّةٌ) أن عائشة معه، وتركت عائشة هذا اللحم ولم يرد أنها كانت تأكل منه؛ فأزواج النبي ﷺ على الصحيح أنه لا يحل لهن الصدقة لأنهن من آله ﷺ، قال ﷺ: (إِنَّ هَذِهِ الصَّدَقَاتِ إِنَّمَا هِيَ أَوْسَاخُ النَّاسِ وَإِنَّهَا لَا تَحِلُّ لِمُحَمَّدٍ وَلَا لِآلِ مُحَمَّدٍ) مسلم، فقد دخل في آل محمد زوجات النبي ﷺ، لكن مواليهن ليسوا في ذلك. وليس في الحديث أن عائشة ﵂ كانت تأكل من اللحم معتقدةً أنه صدقة لها.` },
      { q: `قبول هدية الفقير والمعتَق`, p: `487`,
        n: `الثالثة عشر: جواز قبول هدية الفقير والمعتَق.`,
        o: NO_O,
        s: `فمع كونه فقيرًا إلا أن نفسه تنكسر إذا لم تُقبل منه الهدية، فلذلك شُرع قبول الهدية منه، ولو كان المُهدى إليه أغنى؛ فعائشة ﵂ هي بنت أبي بكر الصديق ﵁ وزوج النبي ﷺ وقبلت الهدية وقبلها النبي ﷺ.` },
      { q: `تحريم الصدقة على رسول الله ﷺ: الفرض والتطوع، ودرجات الترجيح عند الشافعية (الصواب/الصحيح/الأصح)`, p: `487`,
        n: `الرابعة عشر: تحريم الصدقة على رسول الله ﷺ لقولها (وأنت لا تأكل الصدقة). ومذهبنا أنه كانت تحرم عليه صدقة الفرض بلا خلاف وكذا صدقة التطوع على الأصح.`,
        o: NO_O,
        s: `كان ينبغي أن يقول «على الصواب» أو على الأقل يقول «على الصحيح»، فقوله (على الأصح) هو أدنى درجات الترجيح والخلاف فيه قريب. فعندهم درجات في الترجيح: [الصواب وعكسه الباطل والخلاف فيه غير سائغ، الصحيح وعكسه الضعيف والخلاف فيه سائغ، ثم الأصح وعكسه مقابل الأصح والخلاف فيه قريب].` },
      { q: `جواز السجع إذا لم يتكلف، وحكم سجع الكهان`, p: `488`,
        n: `السابعة عشر: جواز السجع إذا لم يتكلف، وإنما نهى عن سجع الكهان ونحوه مما فيه تكلف.`,
        o: NO_O,
        s: `وذلك من قول النبي ﷺ: (فَإِنَّمَا الْوَلَاءُ لِمَنْ أَعْتَقَ) مع (شَرْطُ اللهِ أَحَقُّ وَأَوْثَقُ)، وهناك سجع أيضًا في (كِتَابَ اللهِ أَحَقُّ وَشَرْطُ اللهِ أَوْثَقُ)؛ فالسجع المنهي عنه هو سجع الكهان الذي يُراد به إبطال أدلة الشرع، وكذا ما كان فيه تكلف، فتكلف السجع في الدعاء مذموم وهو يشبه سجع الكهان. وقد قال ذلك النبي ﷺ للرجل الذي أراد أن يُبطل دية الجنين حيث قال: (يَا رَسُولَ اللهِ كَيْفَ أَغْرَمُ مَنْ لَا شَرِبَ وَلَا أَكَلَ وَلَا نَطَقَ وَلَا اسْتَهَلَّ، فَمِثْلُ ذَلِكَ يُطَلُّ)، فَقَالَ رَسُولُ اللهِ ﷺ: «إِنَّمَا هَذَا مِنْ إِخْوَانِ الْكُهَّانِ» من أجل سجعه الذي سجع (مسلم)، وفي رواية لمسلم (وجعل عليهم الدية) فأوجب عليه الدية ولم يلتفت إلى سجعه.` },
      { q: `إعانة المكاتب في كتابته: هل هي من الزكاة الواجبة؟`, p: `488`,
        n: `الثامنة عشر: جواز إعانة المكاتب في كتابته.`,
        o: NO_O,
        s: `الصحيح أنه يُعان من الصدقة ومن الزكاة الواجبة، وفي قوله تعالى (وَفِي الرِّقَابِ وَالْغَارِمِينَ) ومنهم المكاتبون، ومن ذلك شراء الرقاب لإعتاقها.` },
      { q: `تصرّف المرأة الرشيدة في مالها بالشراء والإعتاق والعطايا: هل يُشترط إذن الزوج؟`, p: `488`,
        n: `التاسعة عشر: جواز تصرف المرأة في مالها بالشراء والإعتاق وغيره إذا كانت رشيدة.`,
        o: `مانعو التصرف بغير إذن الزوج: استدلوا بحديث (لا يجوز لامرأة عطية إلا بإذن زوجها)؛ فحمله أحمد على الكثير عرفًا، وحمله مالك على الثلث فما زاد. ومن العلماء من يحمل النهي على الكراهة لا التحريم، وبعضهم يقول إنه منسوخ.`,
        s: `يقصدون دون الرجوع إلى زوجها، وهذه واقعة عين فيها هذا الاحتمال، لكن يُحتمل أن تكون عائشة ﵂ كانت تريد أن تُخبر الرسول ﷺ وهي تعلم أنه يرضى بذلك، ولو علمت المرأة رضا زوجها فلا خلاف في جواز تصرفها في مالها، وإنما منع من منع لقول النبي ﷺ: (لَا يَجُوزُ لِامْرَأَةٍ عَطِيَّةٌ إِلَّا بِإِذْنِ زَوْجِهَا) (د) 3547، وفي رواية: (لَا يَجُوزُ لِامْرَأَةٍ أَمْرٌ فِي مَالِهَا إِذَا مَلَكَ زَوْجُهَا عِصْمَتَهَا) (د) 3546، فحمله أحمد على الكثير عرفًا، وحمله مالك على الثلث فما زاد. والمسألة فيها نزاع مشهور بين العلماء في مسألة تصرف المرأة في الهبات والعطايا فقط، فهل يُشترط فيها إذن الزوج؟ وقد دلَّ الحديث على مشروعية الصدقة دون استئذان الأزواج لأمر النبي ﷺ النساء أن يتصدقن، وكان أمرًا عامًّا، ولا يصح أن يُقال: كل أزواجهن يرضون بالصدقة، والنبي ﷺ حين يُطلق فالأمر يكون مطلقًا؛ فمن العلماء من يحمل النهي على الكثير، ومنهم من يحمل النهي على الكراهة لا على التحريم، والمكروه لا يُطلق عليه حلال مطلقًا، وبعضهم يقول إن هذا منسوخ، والأحاديث في تصرف النساء في أموالهن أصح وأكثر، والأحوط ألا تتصرف المرأة في الهبات والعطايا غير الواجبة عليها في مال كثير أكثر من ثلث مالها، أو ما يُعدُّ عرفًا مالًا كثيرًا، فالأحوط أن تُخبر زوجها. وأما التصرفات في البيع والشراء والمضاربة والشركات فلا شك في صحة تصرفها فيه بدون إذنه لأنه مالها ولا حجر عليها فيه إذا كانت غير سفيهة.` },
      { q: `هل بيع الأمة المزوَّجة طلاق أو فسخ لنكاحها؟`, p: `489`,
        n: `العشرون: أن بيع الأمة المزوجة ليس بطلاق ولا يُفسخ به النكاح، قال جماهير العلماء. وقال سعيد بن المسيب: هو طلاق. وعن ابن عباس أنه ينفسخ به النكاح. وحديث بريرة يرد المذهبين لأنها خُيِّرت في بقائها معه.`,
        o: `سعيد بن المسيب: بيع الأمة المزوجة طلاق. ابن عباس: ينفسخ به النكاح. (وقال بعض العلماء: بيعها طلاقها، تعتد، ثم يُزوِّجها سيدها الجديد لزوجها أو يعاشرها بعد العدة.)`,
        s: `فإنها أُعتقت ثم خُيرت، فهو يدل على وجود العقد مدة بين كونها قد أُعتقت وبين اختيارها لنفسها، لو كان العقد باطلًا بمجرد العتق لكان هناك احتياج إلى تجديد ذلك العقد، ولما كان هناك معنى للتخيير. فالصحيح أن الأمة المزوَّجة إذا بيعت بيعت مزوَّجة، ولا يكون بيعها طلاقًا، بل يكون هذا منفعة مستثناة من ملك المشتري، كما كانت في ملك البائع الأول مستثناة، فإنه إذا اشتراها مزوَّجة فليس له منفعة بضعها، فمنفعة معاشرة ملك اليمين حينئذ ليست في ملك المشتري ولا البائع، لأن البائع رضي زوجها بأن تكون منفعتها قاصرة على الخدمة والرقبة دون منفعة البُضع — الفرج —، وإذا باعها فليس هذا بطلاق، بمعنى أن سيدها الجديد لا يملك أن يعاشرها لأنها مزوجة إلا أن يُطلقها زوجها، وهو قد اشتراها بهذا النقص، فهذا هو الصحيح. والعلماء الذين قالوا بأن بيعها طلاقها قالوا: تعتد ويمكن لسيدها الجديد إما أن يُزوِّجها لزوجها التي كانت تحته أو أن يعاشرها سيدها بعد أن تنتهي العدة، والصحيح الأول وهو قول الجمهور، وهو أن بيع الأمة المزوجة ليس بطلاق ولا فسخ، لأن بريرة عُتقت وظلت مدة، اختارت نفسها وانفسخ النكاح باختيارها لنفسها، إذ المدة بين عتقها واختيارها لنفسها كان العقد باقيًا، إنما عندما قالت اختارت نفسي صارت حرة منفصلة عن زوجها وانفسخ النكاح، والصحيح أن هذا ليس بطلاق بل هو فسخ، بمعنى أنها لو عادت إليه بعد أن يُعتق هو مثلًا بعقد جديد لا يُعدُّ هذا من الطلقات الثلاث.` },
      { q: `جواز اكتساب المكاتب بالسؤال (حكم المسألة والتسول)`, p: `489–490`,
        n: `الحادية والعشرون: جواز اكتساب المكاتب بالسؤال.`,
        o: NO_O,
        s: `بمعنى أن المكاتب الذي يريد تسديد الأقساط يجوز له أن يسأل الناس لأنه محتاج إلى ذلك، وليس فقط بالعمل بل يمكن أن يكون بسؤال الناس، وهو معذور في السؤال لأنه يريد فكاك رقبته، ولو لم يكن له مال إلا السؤال جاز له ذلك. وأما المسألة وهو السؤال — وقد يسمونه التسول — فإنما يجوز لمن لا يجد ما يغنيه، وهو يجوز لثلاثة كما قال ﷺ: «إِنَّ الْمَسْأَلَةَ لَا تَصْلُحُ إِلَّا لِثَلَاثَةٍ لِذِي فَقْرٍ مُدْقِعٍ أَوْ لِذِي غُرْمٍ مُفْظِعٍ أَوْ لِذِي دَمٍ مُوجِعٍ» (د) 1641، قال الأرناؤوط: [إسناده ضعيف، لجهالة حال أبي بكر الحنفي، وللقطعة الأخيرة منه وهي قوله: «إن المسألة …» شواهد تصح بها]. وهذا المكاتب قد أصبح عليه دين بالكتابة، فأصبح من الغارمين، وهو كذلك ضمن قوله تعالى (وَفِي الرِّقَابِ)، ولذلك قوله تعالى (وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ) من أصحاب الحقوق في الزكاة وسائر الأصناف الثمانية يجوز لهم السؤال. أما التسول المذموم فهو محرَّم وهو مع وجود الكفاية.` },
      { q: `احتمال أخف المفسدتين لدفع أعظمهما (تأويل شرط الولاء لأهل بريرة)`, p: `490`,
        n: `الثانية والعشرون: احتمال أخف المفسدتين لدفع أعظمهما، واحتمال مفسدة يسيرة لتحصيل مصلحة عظيمة، على ما بيناه في تأويل شرط الولاء لهم.`,
        o: NO_O,
        s: `وهو أصح الأقوال في ذلك: أن الرسول ﷺ أذن لها في اشتراط هذا الشرط الباطل عقوبةً لهم، ومعاملةً لهم بنقيض قصدهم، فتشترط لهم الولاء ولا يفسد البيع، ولا تكون خدعت البائعين لأن ما أبطله الشرع كالمنعدم، وقد علموا ذلك وقد بلغهم الشرع، فلا خديعة في ذلك. فالصحيح أنها احتملت هذه المفسدة لدفع مفسدة أعظم من اشتراط شروط ليست في كتاب الله، ولدفع مفسدة تعوّد الناس التجرؤ على مخالفة الشرع، ولتحصيل مصلحة عظيمة في عتق الأمة المراد عتقها.` },
      { q: `الشفاعة من الحاكم: هل للحاكم أو الأب أو الزوج أن يُلزم الناس بما ليس بواجب؟ (قوله لبريرة: لا إنما أنا شافع)`, p: `490–492`,
        n: `الثالثة والعشرون: جواز الشفاعة من الحاكم إلى المحكوم له للمحكوم عليه، وجواز الشفاعة إلى المرأة في البقاء مع زوجها.`,
        o: NO_O,
        s: `بمعنى أنه بعدما يحكم له الحاكم يطالبه بالتنازل عن حقه؛ لأن الرسول ﷺ شفع في زوج بريرة، فقال ﷺ: «يَا بَرِيرَةُ اتَّقِي اللهَ فَإِنَّهُ زَوْجُكِ وَأَبُو وَلَدِكِ». فَقَالَتْ: يَا رَسُولَ اللهِ أَتَأْمُرُنِي بِذَلِكَ؟ قَالَ: «لَا إِنَّمَا أَنَا شَافِعٌ» (د) 2231 [قال الألباني: صحيح]. وهذا دليل صحيح على أنه ليس للحاكم أن يُلزِم المحكومين — وليس لولي الأمر أو أمير المؤمنين، وها هو رسول الله ﷺ نفسه لما قالت له (أتأمرني بذلك؟) قال: «لا» — أن يأمر الناس بما لا يلزمهم شرعًا، لأنه إنما تولى أمورهم لا ليأمرهم على هواه، ولكن ليأمرهم بمصالحهم التي وُكلت إليه، وهناك من المصالح التي لم تُوكل إليه كمصالح الناس في تصريف أموالهم، فليس له أن يتصرف فيها هو، فلا يبيع على الناس ولا يشتري لهم ما لم يكن هناك أمر ضروري كالسفيه مثلًا، ولا يُطلِّق رجلٌ من امرأته ولا يُزوِّج رجلٌ رغمًا عنه؛ فالولي إنما جُعلت له الولايات ليتصرف فيها بالمصلحة التي جُعلت له، وهذا كما ذكرنا في فروض الأعيان وفروض الكفايات التي جُعلت إلى الحاكم، بمعنى أنه هو الذي يُحدد من الذي يقوم بها، أما ما لم يكن كذلك فليس له أن يفرض على الناس، إنما يفرض عليهم أن يقيموا صلاة الفريضة، لا يفرض عليهم صلاة النافلة، ويفرض عليهم صيام رمضان ولا يفرض عليهم صيام الإثنين والخميس، ويفرض عليهم الزكاة الواجبة ويأخذها منهم رغمًا عنهم إن امتنعوا، ولا يفرض عليهم صدقة التطوع، ولا يفرض عليهم ما لا يلزمهم؛ وكذا في سائر الولاة ليس لهم أن يفرضوا على الناس ما ليس بواجب ولا فرض عين ولا فرض كفاية، ليس لهم ذلك، وكالأب مثلًا فلا يفرض على ابنه ولا الأم تفرض على ابنها زوجة معينة، ليس لهم ذلك. فالرسول ﷺ تبرأ من أن يكون آمرًا في مثل هذا الأمر، ولذلك لما جاء إلى فاطمة وعلي ﵄ قال لهما: (أَلَا تُصَلِّيَانِ؟) البخاري، ولم يقل لهما «قوما فصليا»؛ ولذا فالأب والعالم والشيخ ونحو ذلك لا يُلزم بما ليس بلازم، فلا يقال للشيخ لتلميذه «فرض عليك أن تفعل كذا وإلا عاقبتك»، بل لا يجوز له أن يعاقب إلا على شيء يستحق العقوبة، فلا يجوز أن تضرب ابنك الذي بلغ عشر سنين لتركه النافلة، تضربه فقط على ترك الفريضة. ولذا فالناس الذين يظنون أن أوامر الحكام تجعل المستحبات والمباحات فرائض ونواهيهم تجعل المباحات محرمات، بل ليس لهم ذلك؛ وقوله (لا إنما أنا شافع) هو الأصل في قول العلماء «إذا كان الإمام عادلًا وجبت طاعته ما لم يُعلم أنها معصية، وإذا لم يكن عدلًا فإنه لا يلزم إلا ما عُلم أنه طاعة». وهنا ما الذي جعلهم يفرقون بين الأمرين؟ هو أن الإمام إذا كان عدلًا فإنه يعرف ما له وما عليه، فلا يُلزم الناس بما ليس بواجب. والنبي ﷺ عندما قالوا له «يا رسول الله سعِّر لنا» فقال: «إِنَّ اللهَ هُوَ الْمُسَعِّرُ، الْقَابِضُ، الْبَاسِطُ، الرَّزَّاقُ، وَإِنِّي لَأَرْجُو أَنْ أَلْقَى رَبِّي وَلَيْسَ أَحَدٌ مِنْكُمْ يَطْلُبُنِي بِمَظْلِمَةٍ فِي دَمٍ وَلَا مَالٍ» (ت) 1314 [قال الألباني: صحيح]، كأنه إذا سعَّر لهم سعرًا دون سعر المثل لكانت هذه مظلمة، وإنما غلا السعر ولا ظلم وليس هناك احتكار ولا ظلم، فهذا مباح، وقد يكون مستحبًّا وذلك بأن غلت الأسعار وكان عندي إمكانية أن أبيع بسعر رخيص، فعليَّ أن أُرخِّص على الناس وأعينهم على ذلك، فالتسعير يقول لهم «بيعوا بسعر كذا حتى لا ترفعوا الأسعار» ومع ذلك فالنبي ﷺ يقول: «وَإِنِّي لَأَرْجُو أَنْ أَلْقَى رَبِّي وَلَيْسَ أَحَدٌ مِنْكُمْ يَطْلُبُنِي بِمَظْلِمَةٍ فِي دَمٍ وَلَا مَالٍ». فالإمام العدل يعرف ما له وما عليه، يعرف ما يجوز أن يأمر الناس به وما لا يجوز أن يأمرهم به بأمر إلزام، فإنه يُرغِّبهم ولا يُلزمهم ولا يُحرِّم عليهم ما لا يجوز؛ ولذلك ليس من حقه أن يقيِّد مطلقات الشرع أطلقها، إلا إذا تسبب ذلك في تسارع الناس إلى حرام. ولذلك قلنا إن فعل عمر ﵁ في طلاق الثلاث من هذا الباب: أنه لم يمنعهم من مباح إلا لأنهم تسارعوا إلى محرَّم، فهو يمنعهم من مباح ليمنعهم من محرَّم؛ والمباح كان أن يُرجعها بعد أن طلقها ثلاثًا بلفظ واحد أو في مجلس واحد، فعمر ﵁ أمضاه عليهم، بمعنى أنك لو طلقتها ثلاثًا فلن أرجعها لك، مع أنه تحل له أن ترجع له، يفعل ذلك معهم لكي يمنعهم من أن يقولوا لفظًا محرَّمًا وهو أن يوقع طلاق الثلاث الذي هو طلاق بدعة فيلعب بكتاب الله وهو بين أظهرهم، فيقول الذي سوف يلعب بكتاب الله: سوف أُمضي ما قاله على نفسه وأُلزمه به وأمنعه مما أُبيح له من إرجاع امرأته التي طلقها ثلاثًا بلفظ واحد. وأما أن يقول الناس إن الحاكم أراد أن يجعل سن الزواج ستة عشرة سنة أو ثماني عشرة سنة أو يجعله عشرين، هو يريد ذلك، ولا بد من طاعة ولي الأمر، فهذا كلام باطل، فليس هذا من طاعة ولي الأمر وليس له ذلك؛ فما المقصود من زيادة سن الزواج هذا، مع وجود النص من الكتاب والسنة والإجماع على الجواز؟ فهذا الأمر تم تحديده في بداية الأمر أيام الملكية مراعاةً لما يريده الغرب، وبعض المشايخ وافق على ذلك، وهذه موافقة باطلة بلا شك، لأن هذا مخالف للنصوص. والآن يريدون أن يزيدوه إلى ثماني عشرة، لماذا؟ في الحقيقة لأن مواثيق الأمم المتحدة تعتبر أن إلى سن الثمانية عشر هم ما زالوا أطفالًا، وذلك في أمر الزواج فقط، أما في أنهم أحرار يتصرفون كما يريدون وفي الفساد والفجور فالباب فيه مفتوح، فبعد اثني عشر سنة لا يتكلم معهم أحد، فبعد اثني عشر سنة لو الأب ضرب ابنه يطلب الابن الشرطة لأبيه؛ فتقييد السن بأنه لا يجوز تزويج أحد قبل ست عشرة سنة وتجريم من تزوج أقل من ذلك، فكيف يُجرِّم شيئًا أحله الله ﷻ؟ يقولون: ولي الأمر أمر بذلك؛ بل نأخذ بأمر ولي الأمر عندما يكون في الأمر مصلحة معتبرة شرعًا كأن يمنعهم من حرام، وليس أن يمنعهم من حلال أحله الله لهم دلَّ عليه الكتاب والسنة والإجماع. ولذلك قلنا بطاعة الإمام العدل لأنه إنما جُعل الأمر له ليأمرهم بما فيه مصلحتهم، وليس لأجل أنه يأمر وينهى؛ ولذا لو أنه قال لرجل «طلِّق امرأتك» لا يلزمه طلاقها؛ ولذا لو أن الزوج قال لزوجته — وهو ولي عليها وله القوامة عليها — «أعطني أموالك التي اشتغلتِ بها»، كيف يأخذ مالها؟ فليس له أن يأخذ هذا المال، ولا يجوز له أن يمنعها من أن تتصرف في مالها تصرفًا مباحًا، فلا يقول لها: أنا زوجك ولا بد أن تطيعي أمري، والرسول ﷺ قال: (وَأَطَاعَتْ زَوْجَهَا، قِيلَ لَهَا: ادْخُلِي الْجَنَّةَ مِنْ أَيِّ أَبْوَابِ الْجَنَّةِ شِئْتِ) (حم) 1661، (حب) 4163، انظر صحيح الجامع: 660؛ بل عليه أن يأمر بما له، كأن يدعوها إلى الفراش أو يأمرها بعدم الخروج من البيت، فله ذلك ويلزمها الطاعة؛ لكن يقول لها على سبيل المثال: تنازلي لي عن مؤخر الصداق، فليس له أن يأمرها بذلك. وكذا الأب والأم إذا طلبا من الابن ما لا يلزمه، كما ذكرنا، كطلاق امرأته التي هي عابدة تقية صالحة، فيطلبون منه طلاقها لأنها لا تريد أن تكشف وجهها أمام إخوته، أو أنه عندما مدَّ أخوه يده ليصافحها لم تُصافحه، فإن أمروه بطلاقها لا يلزمه ذلك وليس لهم ذلك. ولذلك الرسول ﷺ تبرأ من أن يكون آمرًا فقالت: أتأمرني بذلك؟ قال: «لا إنما أنا شافع»، (قالت: لا حاجة لي فيه) (خ) 4979، فردَّت شفاعة الرسول ﷺ، والرسول ﷺ أمضى كلامها ولم يُلزمها بذلك، مع أنه كان يشفع في زوجها الذي كان يبكي ويجري وراءها (فقال رسول الله ﷺ للعباس: «أَلَا تَعْجَبُ مِنْ حُبِّ مُغِيثٍ بَرِيرَةَ، وَبُغْضِ بَرِيرَةَ إِيَّاهُ؟») (خ) 4979، فيتعجب النبي ﷺ من ذلك ومُشفق على مُغيث من كثرة حبه لبريرة. وأما لو كانت المرأة فاسقة — ولا يشترط أن تكون فاسقة، بل قد تكون فيها صفات سيئة، وهناك مضرة على الولد أن يمسكها — فإذا كان أبوك مثل عمر ﵁ وإذا كان أبوك على سُنة إبراهيم فأطعه؛ فإبراهيم ﷺ عندما قال لابنه إسماعيل «غيِّر عتبة بابك» أطاع أباه مباشرةً، فقد كانت امرأة تكفر العشير وليست شاكرةً للنعمة، فقال لها إسماعيل: أنت العتبة، الحقي بأهلك؛ فلو كان على سُنة إبراهيم فتكون هذه النصيحة في مصلحة الابن، ويكون مثله في التقوى والورع، فعند ذلك يلزمه أن يُطيع، فلا يلزم أن يكون نبيًّا بل يكفي أن يكون على طريقه ومنهجه في ذلك. وعمر ﵁ كان يكره امرأة ابن عمر ﵁ وكان ابن عمر ﵁ يحبها، فأمر عمر ابنه بطلاقها، فذهب ابن عمر إلى الرسول ﷺ فقال له ﷺ: «أَطِعْ أَبَاكَ»؛ ولذلك لما سُئل الإمام أحمد عن مثل ذلك فقال: «إن كان أبوك مثل عمر ﵁ فافعل».` },
      { q: `جواز خدمة العتيق لمعتِقه برضاه`, p: `493`,
        n: `الخامسة والعشرون: جواز خدمة العتيق لمعتِقه برضاه.`,
        o: NO_O,
        s: `فهي كانت تأتي لعائشة تخدمها وذلك برضاها وليس إلزامًا، وليس هذا من النعمة المجزاة، أعني أنها لم تأخذ شيئًا نقصت من ثوابها، بل هذا أمر من باب الحب، فكانت تحب عائشة فتخدمها.` },
      { q: `استحباب خطبة الإمام عند وقوع بدعة أو أمر يحتاج إلى بيان، والتلطف في الإنكار دون تسمية الأشخاص`, p: `493`,
        n: `السادسة والعشرون: أنه يُستحب للإمام عند وقوع بدعة أو أمر يحتاج إلى بيانه أن يخطب الناس ويبيِّن لهم حكم ذلك وينكر على من ارتكب ما يخالف الشرع. السابعة والعشرون: استعمال الأدب وحسن العشرة وجميل الموعظة كقوله ﷺ: (ما بال أقوام يشترطون شروطًا ليست في كتاب الله) ولم يواجه صاحب الشرط بعينه لأن المقصود يحصل له ولغيره من غير فضيحة وشناعة عليه.`,
        o: NO_O,
        s: `لأن الرسول ﷺ خطب وبيَّن وقال: (أَمَّا بَعْدُ فَمَا بَالُ أَقْوَامٍ يَشْتَرِطُونَ شُرُوطًا لَيْسَتْ فِي كِتَابِ اللهِ). فلم يقل: يا فلان ويا فلانة، بأسمائهم، وإلى يومنا هذا لا نعرف أسماء أهل بريرة، فلم تُذكر في الأحاديث، وحتى عائشة قالت «أهل بريرة» تأدبًا وسترًا على هؤلاء الذين اشترطوا لهم الولاء، وهؤلاء صحابة ﵃، ومع ذلك لم تُعرف أسماؤهم؛ فينبغي على الإمام والخطيب والمدرس والعالم، إذا كان هناك من نصيحة عامة، ألا يقول أسماء بعض الناس وأفعالهم، فذكر الأسماء على الملأ مما يؤدي إلى نفرة هؤلاء أو نفرة غيرهم. وأما (ما بال أقوام) فهذه قد حققت الغاية المقصودة، فينبغي أن يُراعى ذلك في الخطبة والدرس، وهذا من استعمال الأدب وحسن العشرة وجميل الموعظة.` },
      { q: `الصلاة على النبي ﷺ في الخطبة: هل هي شرط لصحتها؟`, p: `493`,
        n: `التاسعة والعشرون: أنه يُستحب في الخطبة أن يقول بعد حمد الله تعالى والثناء عليه والصلاة على رسول الله ﷺ: (أما بعد)، وقد تكرر هذا في خطب النبي ﷺ وسبق بيانه في مواضع.`,
        o: `الشافعية والحنابلة: يشترطون الصلاة على النبي ﷺ في صحة الخطبة.`,
        s: `دليل الصلاة على النبي ﷺ في الخطب: الشافعية والحنابلة يشترطونها في صحة الخطبة، وإنما هي مشروعة من قول النبي ﷺ: (رَغِمَ أَنْفُ رَجُلٍ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ)، وفي الخطبة تشهُّد، والتشهد يتضمن «أشهد أن محمدًا عبده ورسوله» فيقول «صلى الله عليه وسلم».` },
      { q: `التغليظ في إزالة المنكر والمبالغة في تقبيحه، والمراد بقوله ﷺ «شرط الله أحق»`, p: `494–495`,
        n: `الثلاثون: التغليظ في إزالة المنكر والمبالغة في تقبيحه. قوله ﷺ: (شرط الله أحق): قيل: المراد به قوله تعالى (فإخوانكم في الدين ومواليكم) وقوله تعالى (وما آتاكم الرسول فخذوه) الآية. قال القاضي: وعندي أنه قوله ﷺ (إنما الولاء لمن أعتق). وقوله: (قالوا: إن شاءت تحتسب عليك فلتفعل) معناه إن أرادت الثواب عند الله وألا يكون لها ولاء فلتفعل.`,
        o: `قيل: المراد بـ«شرط الله» قوله تعالى (فإخوانكم في الدين ومواليكم) وقوله (وما آتاكم الرسول فخذوه). وعند القاضي عياض: المراد قوله ﷺ (إنما الولاء لمن أعتق).`,
        s: `(التغليظ) لأن الرسول ﷺ قال كلامًا شديدًا، قال: «فَهُوَ بَاطِلٌ وَإِنْ كَانَ مِائَةَ شَرْطٍ وَشَرْطُ اللهِ أَحَقُّ وَأَوْثَقُ، مَا بَالُ رِجَالٍ مِنْكُمْ يَقُولُ أَحَدُهُمْ أَعْتِقْ فُلَانًا وَالْوَلَاءُ لِي إِنَّمَا الْوَلَاءُ لِمَنْ أَعْتَقَ»، فكل هذا من التغليظ في إزالة المنكر والمبالغة في تقبيحه. (شرط الله) فيكون الولاء لمن أعتق، أو الحكم الظاهر أن الرسول ﷺ قال «إنما الولاء لمن أعتق» وقد بيَّن ذلك؛ وهذا أظهر: أنه شرط الله وهو في كتاب الله فهو فرضه، وفي كتاب الله الآيات الآمرة باتباع الرسول ﷺ، وقد قال ﷺ: «إِنَّمَا الْوَلَاءُ لِمَنْ أَعْتَقَ». (وقوله: تحتسب عليك) أي في الدنيا.`,
        f: [
          `(ص494 هامش6) على قوله «الأوقية الحجازية أربعون درهمًا»: قد سبق بيان الدرهم وأنه بالجرامات المعاصرة (2,975) جرام من الفضة الخالصة.`,
          `(ص495 هامش1) على قوله «لا هاء الله ذا» (وأنه قسم): فبدل واو القسم وضعوا الهاء، وكلها من أدوات القسم.`,
        ] },
    ],
  },
];
